CREATE OR REPLACE VIEW public.metrics_conversion_events WITH(security_invoker=true) AS SELECT a.entity_id::uuid AS opportunity_id,a.created_at AS reached_at,a.id AS event_id FROM public.audit_log a WHERE a.entity_table='opportunities' AND a.entity_id ~ '^[0-9a-fA-F-]{36}$' AND a.before_data IS NOT NULL AND a.before_data->>'stage' IS DISTINCT FROM 'pending_contract' AND a.after_data->>'stage'='pending_contract' AND a.action IN('OPPORTUNITY_MOVE','OPPORTUNITY_STAGE','MOVE_OPPORTUNITY','UPDATE','OPPORTUNITY_STAGE_CHANGED');
CREATE OR REPLACE FUNCTION public.metrics_inventory(_scope jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH u AS(SELECT * FROM public.metrics_unit_scope u WHERE public.metrics_scope_match(u,_scope)), totals AS(SELECT count(*) AS total,count(*) FILTER(WHERE publish_state='published') AS published,count(*) FILTER(WHERE publish_state='draft') AS draft,count(*) FILTER(WHERE publish_state NOT IN('draft','published')) AS unpublished,count(*) FILTER(WHERE publish_state='published' AND leasing_status='leased') AS leased,count(*) FILTER(WHERE publish_state='published' AND leasing_status IN('leased','on_hold','pending_contract')) AS occupied FROM u), grouped AS(SELECT 'building' AS dimension,building_number::text AS key,'مبنى '||building_number::text AS label,publish_state,coalesce(leasing_status::text,'review') AS status,count(*) AS count FROM u GROUP BY building_number,publish_state,leasing_status UNION ALL SELECT 'activity',coalesce(activity_id::text,'unassigned'),coalesce(activity_name,'نشاط غير محدد'),publish_state,coalesce(leasing_status::text,'review'),count(*) FROM u GROUP BY activity_id,activity_name,publish_state,leasing_status) SELECT to_jsonb(t)||jsonb_build_object('leased_rate',public.metrics_ratio(t.leased,t.published),'occupancy_rate',public.metrics_ratio(t.occupied,t.published),'groups',coalesce((SELECT jsonb_agg(to_jsonb(g)) FROM grouped g),'[]')) FROM totals t $$;
CREATE OR REPLACE FUNCTION public.metrics_opportunity_matches(_id uuid,_scope jsonb) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.opportunities o WHERE o.id=_id AND ((nullif(_scope->>'building','') IS NULL AND nullif(_scope->>'phase','') IS NULL AND nullif(_scope->>'unit_type','') IS NULL AND (nullif(_scope->>'activity','') IS NULL OR o.activity_id::text=_scope->>'activity' OR (_scope->>'activity'='unassigned' AND o.activity_id IS NULL))) OR EXISTS(SELECT 1 FROM public.metrics_unit_scope u WHERE public.metrics_scope_match(u,_scope) AND (u.id=ANY(o.preferred_unit_ids) OR EXISTS(SELECT 1 FROM public.booking_units bu WHERE bu.booking_id=o.booking_id AND bu.unit_id=u.id))))) $$;
CREATE OR REPLACE FUNCTION public.metrics_pipeline(_scope jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH o AS(SELECT * FROM public.opportunities o WHERE public.metrics_opportunity_matches(o.id,_scope) AND (o.preferred_unit_ids IS NULL OR cardinality(o.preferred_unit_ids)=0 OR EXISTS(SELECT 1 FROM public.metrics_unit_scope u WHERE u.id=ANY(o.preferred_unit_ids)))), stage_counts AS(SELECT stage,count(*) AS count FROM o WHERE outcome IS NULL GROUP BY stage), b AS(SELECT b.* FROM public.bookings b WHERE archived_at IS NULL AND EXISTS(SELECT 1 FROM public.booking_units bu JOIN public.metrics_unit_scope u ON u.id=bu.unit_id WHERE bu.booking_id=b.id AND public.metrics_scope_match(u,_scope))), events AS(SELECT count(DISTINCT e.opportunity_id) AS converted FROM public.metrics_conversion_events e JOIN o ON o.id=e.opportunity_id WHERE e.reached_at>=((_scope->>'from')::date::timestamp AT TIME ZONE 'Asia/Riyadh') AND e.reached_at<(((_scope->>'to')::date+1)::timestamp AT TIME ZONE 'Asia/Riyadh')), req AS(SELECT count(*) AS requests FROM b WHERE created_at>=((_scope->>'from')::date::timestamp AT TIME ZONE 'Asia/Riyadh') AND created_at<(((_scope->>'to')::date+1)::timestamp AT TIME ZONE 'Asia/Riyadh')) SELECT jsonb_build_object('stages',coalesce((SELECT jsonb_agg(to_jsonb(s)) FROM stage_counts s),'[]'),'holds_expiring_24h',(SELECT count(*) FROM b WHERE status='pending' AND expires_at>=now() AND expires_at<now()+interval '24 hours' AND EXISTS(SELECT 1 FROM public.booking_units bu JOIN public.metrics_unit_scope u ON u.id=bu.unit_id WHERE bu.booking_id=b.id AND u.leasing_status='on_hold' AND public.metrics_scope_match(u,_scope))),'booking_requests',req.requests,'converted_opportunities',events.converted,'conversion_rate',public.metrics_ratio(events.converted,req.requests),'event_coverage','partial_audit_history') FROM req,events $$;
CREATE OR REPLACE FUNCTION public.metrics_finance(_scope jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH factors AS(SELECT cu.contract_id,sum(cu.annual_rent_excl_vat)/nullif(c.annual_rent_excl_vat,0) AS factor,sum(cu.annual_rent_excl_vat) AS rent FROM public.contract_units cu JOIN public.contracts c ON c.id=cu.contract_id JOIN public.metrics_unit_scope u ON u.id=cu.unit_id WHERE public.metrics_scope_match(u,_scope) GROUP BY cu.contract_id,c.annual_rent_excl_vat), i AS(SELECT i.*,f.factor FROM public.metrics_installment_balances i JOIN factors f ON f.contract_id=i.contract_id WHERE i.due_date BETWEEN (_scope->>'from')::date AND (_scope->>'to')::date), receipts AS(SELECT r.*,CASE WHEN nullif(_scope->>'building','') IS NULL AND nullif(_scope->>'phase','') IS NULL AND nullif(_scope->>'activity','') IS NULL AND nullif(_scope->>'unit_type','') IS NULL THEN 1 ELSE coalesce(f.factor,0) END AS factor FROM public.metrics_receipt_scope r LEFT JOIN factors f ON f.contract_id=r.contract_id WHERE r.paid_at>=((_scope->>'from')::date::timestamp AT TIME ZONE 'Asia/Riyadh') AND r.paid_at<(((_scope->>'to')::date+1)::timestamp AT TIME ZONE 'Asia/Riyadh') AND (r.contract_id IS NULL OR EXISTS(SELECT 1 FROM factors f WHERE f.contract_id=r.contract_id))), grace AS(SELECT coalesce((SELECT grace_days FROM public.app_settings ORDER BY id LIMIT 1),3) AS days), sums AS(SELECT coalesce(sum(remaining_excl*factor) FILTER(WHERE due_date<(now() AT TIME ZONE 'Asia/Riyadh')::date),0) AS due_excl,coalesce(sum(remaining_vat*factor) FILTER(WHERE due_date<(now() AT TIME ZONE 'Asia/Riyadh')::date),0) AS due_vat,coalesce(sum(remaining_excl*factor) FILTER(WHERE public.metrics_is_overdue(due_date,(now() AT TIME ZONE 'Asia/Riyadh')::date,(SELECT days FROM grace))),0) AS overdue_excl,coalesce(sum(remaining_vat*factor) FILTER(WHERE public.metrics_is_overdue(due_date,(now() AT TIME ZONE 'Asia/Riyadh')::date,(SELECT days FROM grace))),0) AS overdue_vat,coalesce(sum(amount_incl_vat*factor),0) AS obligation_incl,coalesce(sum((paid_excl+paid_vat)*factor),0) AS allocated_incl FROM i) SELECT to_jsonb(s)||jsonb_build_object('annual_rent_excl_vat',coalesce((SELECT sum(f.rent) FROM factors f JOIN public.contracts c ON c.id=f.contract_id WHERE c.status='active'),0),'annual_rent_vat',coalesce((SELECT sum(f.rent*c.vat_rate/100) FROM factors f JOIN public.contracts c ON c.id=f.contract_id WHERE c.status='active'),0),'collected_excl',coalesce((SELECT sum(amount_excl_vat*factor) FROM receipts),0),'collected_vat',(SELECT sum(vat_amount*factor) FROM receipts),'unallocated_excl',coalesce((SELECT sum(greatest(0,amount_excl_vat-allocated_excl)*factor) FROM receipts),0),'collection_rate',public.metrics_ratio(s.allocated_incl,s.obligation_incl),'grace_days',(SELECT days FROM grace),'receipts_to_verify',(SELECT count(*) FROM public.receipts r WHERE r.status='recorded' AND r.reverses_id IS NULL AND r.archived_at IS NULL AND NOT EXISTS(SELECT 1 FROM public.receipt_legacy_sources l WHERE l.receipt_id=r.id AND l.resolution<>'distinct') AND (EXISTS(SELECT 1 FROM factors f WHERE f.contract_id=r.contract_id) OR (r.contract_id IS NULL AND nullif(_scope->>'building','') IS NULL AND nullif(_scope->>'phase','') IS NULL AND nullif(_scope->>'activity','') IS NULL AND nullif(_scope->>'unit_type','') IS NULL))),'legacy_sources_pending',(SELECT count(*) FROM public.receipt_legacy_sources WHERE resolution='review'),'coverage','approved_sources_only') FROM sums s $$;
CREATE OR REPLACE FUNCTION public.metrics_quality(_scope jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH u AS(SELECT * FROM public.metrics_unit_scope u WHERE public.metrics_scope_match(u,_scope)) SELECT jsonb_build_object('incomplete_units',(SELECT count(*) FROM u WHERE building_id IS NULL OR activity_id IS NULL OR coalesce(area_m2,0)<=0 OR unit_type IS NULL),'status_review',(SELECT count(*) FROM public.unit_status_backfill_review r JOIN u ON u.id=r.unit_id WHERE r.resolved_at IS NULL),'duplicate_candidates',CASE WHEN _scope->>'building' IS NULL AND _scope->>'phase' IS NULL AND _scope->>'activity' IS NULL AND _scope->>'unit_type' IS NULL THEN (SELECT count(*) FROM public.duplicate_candidates WHERE status='pending') ELSE NULL END,'prompt11',NULL,'prompt11_available',false) $$;
CREATE OR REPLACE FUNCTION public.metrics_pending_approvals(_scope jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('transfers',(SELECT count(*) FROM public.transfer_requests t WHERE t.status='pending' AND public.metrics_opportunity_matches(t.opportunity_id,_scope))) $$;
CREATE OR REPLACE FUNCTION public._metrics_snapshot(_scope jsonb,_audience text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE s jsonb:=coalesce(_scope,'{}');result jsonb;BEGIN IF jsonb_typeof(s)<>'object' OR octet_length(s::text)>16000 THEN RAISE EXCEPTION 'نطاق غير صالح'; END IF; s:=s||jsonb_build_object('from',coalesce(nullif(s->>'from',''),to_char(date_trunc('month',now() AT TIME ZONE 'Asia/Riyadh'),'YYYY-MM-DD')),'to',coalesce(nullif(s->>'to',''),to_char(now() AT TIME ZONE 'Asia/Riyadh','YYYY-MM-DD')));IF (s->>'from')::date>(s->>'to')::date THEN RAISE EXCEPTION 'فترة غير صالحة'; END IF;result:=jsonb_build_object('as_of',now(),'scope',s,'audience',_audience,'inventory',public.metrics_inventory(s),'options',jsonb_build_object('buildings',(SELECT jsonb_agg(DISTINCT building_number) FROM public.metrics_unit_scope),'phases',(SELECT jsonb_agg(DISTINCT phase) FROM public.metrics_unit_scope),'activities',(SELECT jsonb_agg(x) FROM (SELECT DISTINCT activity_id AS id,coalesce(activity_name,'نشاط غير محدد') AS name FROM public.metrics_unit_scope)x),'unit_types',(SELECT jsonb_agg(DISTINCT unit_type) FROM public.metrics_unit_scope)));IF _audience IN('admin','manager','investor','leasing_manager','service') THEN result:=result||jsonb_build_object('pipeline',public.metrics_pipeline(s));END IF;IF _audience IN('admin','manager','investor','accountant','service') THEN result:=result||jsonb_build_object('finance',public.metrics_finance(s));END IF;IF _audience IN('admin','manager','service') THEN result:=result||jsonb_build_object('quality',public.metrics_quality(s));END IF;IF _audience IN('admin','leasing_manager','service') THEN result:=result||jsonb_build_object('approvals',public.metrics_pending_approvals(s));END IF;IF _audience='control' THEN result:=jsonb_build_object('as_of',now(),'scope',s,'audience','control','maintenance',(SELECT count(*) FROM public.metrics_unit_scope u WHERE u.leasing_status='maintenance' AND public.metrics_scope_match(u,s)),'options',result->'options');END IF;RETURN result;END $$;
CREATE OR REPLACE FUNCTION public.metrics_snapshot(_scope jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE role_name text;BEGIN SELECT role::text INTO role_name FROM public.user_roles WHERE user_id=auth.uid() AND is_active AND role IN('admin','manager','investor','leasing_manager','accountant','control') ORDER BY CASE role WHEN 'admin' THEN 0 WHEN 'manager' THEN 1 WHEN 'investor' THEN 2 WHEN 'leasing_manager' THEN 3 WHEN 'accountant' THEN 4 ELSE 5 END LIMIT 1;IF role_name IS NULL THEN RAISE EXCEPTION 'غير مسموح بعرض المؤشرات' USING ERRCODE='42501';END IF;RETURN public._metrics_snapshot(_scope,role_name);END $$;
CREATE OR REPLACE FUNCTION public.metrics_service_snapshot(_scope jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public._metrics_snapshot(_scope,'service') $$;
REVOKE ALL ON FUNCTION public.metrics_inventory(jsonb),public.metrics_pipeline(jsonb),public.metrics_finance(jsonb),public.metrics_quality(jsonb),public.metrics_pending_approvals(jsonb),public.metrics_opportunity_matches(uuid,jsonb),public._metrics_snapshot(jsonb,text),public.metrics_service_snapshot(jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.metrics_inventory(jsonb),public.metrics_pipeline(jsonb),public.metrics_finance(jsonb),public.metrics_quality(jsonb),public.metrics_pending_approvals(jsonb),public.metrics_opportunity_matches(uuid,jsonb),public._metrics_snapshot(jsonb,text),public.metrics_service_snapshot(jsonb) TO service_role;
REVOKE ALL ON FUNCTION public.metrics_snapshot(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.metrics_snapshot(jsonb) TO authenticated,service_role;
SELECT to_regprocedure('public.metrics_snapshot(jsonb)') IS NOT NULL AS snapshot_ready,has_function_privilege('authenticated','public.metrics_service_snapshot(jsonb)','EXECUTE') AS service_access_must_be_false;